package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicLong;
public class PreparedSnapshotTest {
 @Test public void snapshotsOwnTheirListAndNestedObjects()throws Exception{TorrentRulesTest.Memory storage=new TorrentRulesTest.Memory();DownloadStation model=new DownloadStation(new TorrentRulesTest.Fake(storage),storage,"user");model.prepare("https://example.org/a.torrent",null,null,"video");List<JSONObject> copy=model.snapshotPrepared();copy.get(0).put("submitted",true);copy.get(0).getJSONArray("files").getJSONObject(0).put("name","changed");List<JSONObject> fresh=model.snapshotPrepared();assertFalse(fresh.get(0).getBoolean("submitted"));assertNotEquals("changed",fresh.get(0).getJSONArray("files").getJSONObject(0).getString("name"));copy.clear();assertEquals(1,model.snapshotPrepared().size());}
 @Test(timeout=30000) public void expiryAndSnapshotsAreSafeForTwentyThousandIterations()throws Exception{AtomicLong clock=new AtomicLong(100*SubmittedExpiryTest.HOUR);TorrentRulesTest.Memory storage=new TorrentRulesTest.Memory();TorrentRulesTest.Fake transport=new TorrentRulesTest.Fake(storage);DownloadStation model=new DownloadStation(transport,storage,"user",clock::get);synchronized(model){model.prepared.put("draft",new JSONObject().put("list_id","draft").put("submitted",false));}CountDownLatch start=new CountDownLatch(1);ExecutorService threads=Executors.newFixedThreadPool(2);try{Future<?> writer=threads.submit(()->{start.await();for(int i=0;i<20000;i++){synchronized(model){model.prepared.put("expired",new JSONObject().put("list_id","expired").put("submitted",true).put("submitted_at",clock.get()));}clock.addAndGet(25*SubmittedExpiryTest.HOUR);model.pruneSubmitted();}return null;});Future<?> reader=threads.submit(()->{start.await();for(int i=0;i<20000;i++){List<JSONObject> snapshot=model.snapshotPrepared();assertTrue(snapshot.stream().anyMatch(item->"draft".equals(item.optString("list_id"))));for(JSONObject item:snapshot)item.put("copy_only",true);snapshot.clear();}return null;});start.countDown();writer.get(25,TimeUnit.SECONDS);reader.get(25,TimeUnit.SECONDS);assertEquals(1,model.snapshotPrepared().size());assertFalse(model.snapshotPrepared().get(0).has("copy_only"));assertTrue(transport.calls.isEmpty());}finally{threads.shutdownNow();}}
}
